package com.sorenkai.api.model

import kotlinx.serialization.Serializable
import kotlin.time.Instant

/**
 * Represents an immutable audit log entry.
 *
 * Audit logs capture all user-facing modifications for compliance,
 * debugging, and accountability. Each entry is append-only and is not
 * expected to be edited or deleted.
 *
 * @property id Unique identifier for this log entry (generated by [newId]).
 * @property entityType Type of entity being tracked (e.g., WRITING, DISCUSSION).
 * @property entityId Identifier of the specific entity instance.
 * @property action The action performed on the entity (CREATE, EDIT, DELETE).
 * @property userId The UID of the user who performed the action.
 * @property changes Key–value map describing what fields were changed (e.g., `"body" -> "updated"`).
 * @property timestamp Time when the action was logged (defaults to [now]).
 * @property ip Optional IP address of the user at the time of the action.
 */
@Serializable
data class AuditLog(
    val id: String = com.sorenkai.api.util.newId(),
    val entityType: EntityType,
    val entityId: String,
    val action: Action,
    val userId: String,
    val changes: Map<String, String?> = emptyMap(),
    val timestamp: Instant = com.sorenkai.api.util.now(),
    val ip: String? = null
) {
    /**
     * The type of entity that can be audited.
     */
    @Serializable
    enum class EntityType { WRITING, DISCUSSION }

    /**
     * The type of action being recorded in the audit log.
     */
    @Serializable
    enum class Action { CREATE, EDIT, DELETE }
}
